    if not data: return
    n=data[0]; pts=[None]*n
    for i in range(n):
        x,y=data[1+2*i:3+2*i]; pts[x-1]=y-1
    # Integer bitsets of points incomparable with each point, including itself.
    inc=[0]*n
    for i in range(n):
        for j in range(n):
            if i==j or ((i<j and pts[i]>pts[j]) or (i>j and pts[i]<pts[j])):
                inc[i] |= 1<<j
    seen={ (1<<n)-1 }
