import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))

    factors = []
    primes = set()
    for x in a:
        d = {}
        q = 2
        while q * q <= x:
            while x % q == 0:
                d[q] = d.get(q, 0) + 1
                x //= q
            q += 1
        if x > 1:
            d[x] = d.get(x, 0) + 1
        factors.append(d)
        primes.update(d)

    answer = 1
    for p in primes:
        weights = [d.get(p, 0) for d in factors]
        max_height = sum(weights)
        powers = [1] * (max_height + 1)
        for h in range(1, max_height + 1):
            powers[h] = powers[h - 1] * p % MOD

        # dp[h] is the weighted sum for walks whose current height,
        # relative to their minimum so far, is h.
        dp = {0: 1}
        vertices = 1
        for w in weights:
            nxt = {}
            if w == 0:
                for h, value in dp.items():
                    nxt[h] = value * powers[h] % MOD
            else:
                for h, value in dp.items():
                    nh = h + w
                    nxt[nh] = (nxt.get(nh, 0) + value * powers[nh]) % MOD
                    if h >= w:
                        nh = h - w
                        nxt[nh] = (nxt.get(nh, 0) + value * powers[nh]) % MOD
                    else:
                        # The new step makes a lower minimum. All previous
                        # vertices gain (w-h) in normalized exponent.
                        delta = w - h
                        nxt[0] = (nxt.get(0, 0) + value * pow(p, vertices * delta, MOD)) % MOD
            dp = nxt
            vertices += 1

        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

