import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:1 + n]
    limit = max(values)

    # Smallest prime factor for every value up to the maximum input.
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    nim_sum = 0
    for value in values:
        count = 0
        while value > 1:
            prime = spf[value]
            while value % prime == 0:
                value //= prime
                count += 1
        nim_sum ^= count

    print("Anna" if nim_sum else "Bruno")

if __name__ == "__main__":
    main()

