class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        heap = []  # (-left endpoint, pair id), for constraints already active
        gains = [0] * len(conflictingPairs)
        total = 0
        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                heapq.heappush(heap, (-left, idx))

            if not heap:
                total += right
                continue

            neg_top, idx = heapq.heappop(heap)
            top = -neg_top
            second = -heap[0][0] if heap else 0
            heapq.heappush(heap, (neg_top, idx))

            total += right - top
            gains[idx] += top - second

        return total + max(gains)

