import sys

def solve():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = []
    for _ in range(M):
        a, b, c = map(int, input().split())
        edges.append((a - 1, b - 1, c))

    queries = []
    deleted = [False] * M
    for _ in range(Q):
        q = list(map(int, input().split()))
        if q[0] == 1:
            i = q[1] - 1
            deleted[i] = True
            queries.append((1, i))
        else:
            queries.append((2, q[1] - 1, q[2] - 1))

    INF = 10**30
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not deleted[i]:
            dist[a][b] = dist[b][a] = c

    # APSP after all deletions.
    for k in range(N):
        row_k = dist[k]
        for i in range(N):
            dik = dist[i][k]
            if dik == INF:
                continue
            row_i = dist[i]
            for j in range(N):
                nd = dik + row_k[j]
                if nd < row_i[j]:
                    row_i[j] = nd

    answers = []
    for q in reversed(queries):
        if q[0] == 2:
            d = dist[q[1]][q[2]]
            answers.append(str(-1 if d == INF else d))
        else:
            u, v, w = edges[q[1]]
            if dist[u][v] <= w:
                continue
            # Inserting one undirected edge: a new shortest path uses it at most once.
            to_u = [dist[i][u] for i in range(N)]
            to_v = [dist[i][v] for i in range(N)]
            for i in range(N):
                row = dist[i]
                via_uv = to_u[i] + w
                via_vu = to_v[i] + w
                row[:] = [min(old, via_uv + to_v[j], via_vu + to_u[j])
                          for j, old in enumerate(row)]

    sys.stdout.write('\n'.join(reversed(answers)))

if __name__ == '__main__':
    solve()

