import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    vals = data[2:]
    processes = [tuple(vals[4*i:4*i+4]) for i in range(n)]

    def minimum_cost(target, a, p, b, q):
        g = gcd(a, b)
        if p * b <= q * a:
            # S is no more expensive per unit capacity. Any A/g T-machines
            # can be replaced by B/g S-machines at no greater cost.
            best = 10**30
            for y in range(a // g):
                remaining = target - b * y
                x = (remaining + a - 1) // a if remaining > 0 else 0
                best = min(best, x * p + y * q)
            return best
        else:
            # Symmetrically, an optimum needs fewer than B/g S-machines.
            best = 10**30
            for x in range(b // g):
                remaining = target - a * x
                y = (remaining + b - 1) // b if remaining > 0 else 0
                best = min(best, x * p + y * q)
            return best

    def feasible(target):
        total = 0
        for a, p, b, q in processes:
            total += minimum_cost(target, a, p, b, q)
            if total > budget:
                return False
        return True

    low, high = 0, 10**9 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

