class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)

        # For a number x > 1, the first operation produces popcount(x).
        # Thus x is reducible in at most k steps exactly when
        # popcount(x) reaches 1 in at most k-1 further steps.
        good = [False] * (m + 1)
        for bits in range(1, m + 1):
            value = bits
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[bits] = steps + 1 <= k

        # Count numbers smaller than s by their first differing bit. For each
        # position where s has a 1, fix 0 there and freely choose the suffix.
        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = m - i - 1
                ways = 1  # C(remaining, 0)
                for suffix_ones in range(remaining + 1):
                    if good[prefix_ones + suffix_ones]:
                        answer = (answer + ways) % MOD
                    if suffix_ones < remaining:
                        ways = ways * (remaining - suffix_ones) // (suffix_ones + 1)
                prefix_ones += 1

        return answer

