import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    n = int(input())
    a = [input().strip() for _ in range(n)]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    dist = [[-1] * n for _ in range(n)]
    q = deque()

    # Empty paths are palindromes.
    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))

    # A single edge is a palindrome of length one.
    for i in range(n):
        for j, ch in enumerate(a[i]):
            if ch != '-':
                c = ord(ch) - ord('a')
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    q.append((i, j))

    # Extend a known palindrome at both ends by equally labeled edges.
    while q:
        x, y = q.popleft()
        new_dist = dist[x][y] + 2
        for c in range(26):
            for u in incoming[x][c]:
                row = dist[u]
                for v in outgoing[y][c]:
                    if row[v] == -1:
                        row[v] = new_dist
                        q.append((u, v))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

