    # Each initial edge is lifted to its positive representative; offsets
    # of the two chosen coordinate paths must not cross either endpoint.
    dp={}
    for disp,cost in opts[0]: dp[disp]=(cost,disp)
    for i in range(1,n):
        nd={}
