class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # p[i] is the contribution of a digit in decimal position i modulo k.
        p = [1 % k] * n
        for i in range(1, n):
            p[i] = (p[i - 1] * 10) % k

        # Each variable is one digit in the first half. Its coefficient includes
        # both mirrored positions (or just the center position).
        coeff = [
            (p[i] + (p[n - 1 - i] if i != n - 1 - i else 0)) % k
            for i in range(m)
        ]

        # dp[i][r]: using variables i..m-1, it is possible to obtain
        # a total contribution of r modulo k. The leading digit restriction
        # is applied separately while constructing the answer.
        dp = [bytearray(k) for _ in range(m + 1)]
        dp[m][0] = 1
        for i in range(m - 1, -1, -1):
            nxt = dp[i + 1]
            cur = dp[i]
            c = coeff[i]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - d * c) % k]:
                        cur[r] = 1
                        break

        # Greedily fix each digit from largest to smallest while preserving
        # the possibility of completing a number divisible by k.
        digits = []
        need = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                remaining = (need - d * c) % k
                if dp[i + 1][remaining]:
                    digits.append(str(d))
                    need = remaining
                    break

        half = ''.join(digits)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

