from typing import List
class Solution:
 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums)
  ng=[n]*n; st=[]
  for i in range(n-1,-1,-1):
   while st and nums[st[-1]]<=nums[i]: st.pop()
   ng[i]=st[-1] if st else n
   st.append(i)
  LOG=n.bit_length()
  nxt=[ng]
  agg=[[((ng[i]-i)*nums[i]) if ng[i]<n else 0 for i in range(n)]]
  for j in range(1,LOG):
   p=nxt[-1]; a=agg[-1]
   q=[n]*n; b=[0]*n
   for i in range(n):
    mid=p[i]
    if mid<n:
     q[i]=p[mid]; b[i]=a[i]+a[mid]
   nxt.append(q); agg.append(b)
  pref=[0]
  for x in nums: pref.append(pref[-1]+x)
  def cost(l,r):
   pos=l; s=0
   for j in range(LOG-1,-1,-1):
    en=nxt[j][pos]
    if en<=r:
     s+=agg[j][pos]; pos=en
   s+=(r-pos+1)*nums[pos]
   return s-(pref[r+1]-pref[l])
  ans=0
  for r in range(n):
   lo,hi=0,r
   while lo<hi:
    mid=(lo+hi)//2
    if cost(mid,r)<=k: hi=mid
    else: lo=mid+1
   ans+=r-lo+1
  return ans

