from typing import List
class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges)+1
        g=[[] for _ in range(n)]
        for u,v,w in edges:
            g[u].append((v,w)); g[v].append((u,w))
        parent=[-1]*n
        pw=[0]*n
        order=[0]
        parent[0]=0
        for u in order:
            for v,w in g[u]:
                if v != parent[u]:
                    parent[v]=u; pw[v]=w; order.append(v)
        d0=[0]*n; d1=[0]*n
        for u in reversed(order):
            base=0; gains=[]
            for v,w in g[u]:
                if parent[v]==u:
                    base += d0[v]
                    gains.append(w+d1[v]-d0[v])
            gains.sort(reverse=True)
            pref=[0]
            for x in gains: pref.append(pref[-1]+max(0,x))
            d0[u]=base+pref[min(k,len(gains))]
            d1[u]=base+pref[min(max(0,k-1),len(gains))]
        return d0[0]

