    dp[0] = 0

    for i in range(n):
        w, v = items[2 * i], items[2 * i + 1]
        nd = [neg] * (W + 1)
        for r in range(min(w, W + 1)):
            lines = []
            head = 0
            limit = (W - r) // w
            for j in range(limit + 1):
                old = dp[r + j * w]
                if old != neg:
                    slope = 2 * j
                    intercept = old - j * j - j * v
                    while len(lines) - head >= 2:
                        m1, b1 = lines[-2]
                        m2, b2 = lines[-1]
                        if (b2 - b1) * (slope - m2) <= (intercept - b2) * (m2 - m1):
                            lines.pop()
                        else:
                            break
                    lines.append((slope, intercept))

                while len(lines) - head >= 2:
                    m1, b1 = lines[head]
                    m2, b2 = lines[head + 1]
                    if m2 * j + b2 >= m1 * j + b1:
                        head += 1
                    else:
                        break
                if head < len(lines):
                    m, b = lines[head]
                    nd[r + j * w] = -j * j + j * v + m * j + b
        dp = nd

    print(max(dp))

