from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Iterative postorder traversal; reversed pushes preserve ascending child order.
        order = []
        stack = [(0, False)]
        while stack:
            v, exiting = stack.pop()
            if exiting:
                order.append(v)
            else:
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))

        text = ''.join(s[v] for v in order)
        subtree_size = [1] * n
        end = [0] * n
        for i, v in enumerate(order):
            end[v] = i
            for child in children[v]:
                subtree_size[v] += subtree_size[child]

        # Manacher radii support constant-time palindrome checks for every interval.
        m = len(text)
        odd = [0] * m
        left, right = 0, -1
        for i in range(m):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < m and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * m
        left, right = 0, -1
        for i in range(m):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < m and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            length = subtree_size[v]
            start = end[v] - length + 1
            if length % 2:
                answer[v] = odd[start + length // 2] >= length // 2 + 1
            else:
                answer[v] = even[start + length // 2] >= length // 2
        return answer

