class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        # dp[c] is the resulting length after the current number
        # of transformations, starting from the single letter c.
        dp = [1] * 26
        for _ in range(t):
            nxt = [0] * 26
            for c in range(25):
                nxt[c] = dp[c + 1]
            nxt[25] = (dp[0] + dp[1]) % mod
            dp = nxt
        return sum(dp[ord(ch) - ord('a')] for ch in s) % mod

