class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = 10 ** len(str(n))
        prime = [True] * limit
        prime[0] = False
        if limit > 1:
            prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                count = (limit - 1 - p * p) // p + 1
                prime[p * p:limit:p] = [False] * count

        if prime[n] or prime[m]:
            return -1

        inf = float('inf')
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            digits = list(str(x))
            for i, char in enumerate(digits):
                digit = ord(char) - ord('0')
                place = 10 ** (len(digits) - i - 1)
                if digit < 9:
                    nxt = x + place
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))
                minimum = 1 if i == 0 else 0
                if digit > minimum:
                    nxt = x - place
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))

        return -1

