class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] is the LCP length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # Count splits where nums1 is a prefix of nums2.
        first_count = 0
        first_works = [False] * n
        for i in range(1, n - 1):
            if z[i] >= i:
                first_works[i] = True
                first_count += n - 2 * i

        # LCP row for each starting index, computed using the next row:
        # lcp(i, j) = 1 + lcp(i+1, j+1) when nums[i] == nums[j].
        # Count splits where nums2 is a prefix of nums3, and the overlap
        # with the first condition so it is not counted twice.
        second_count = overlap = 0
        next_row = [0] * n
        for i in range(n - 2, 0, -1):
            row = [0] * n
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    row[j] = 1 + (next_row[j + 1] if j + 1 < n else 0)
                    if row[j] >= j - i:
                        second_count += 1
                        if first_works[i] and j >= 2 * i:
                            overlap += 1
            next_row = row

        return first_count + second_count - overlap

