        weights = []
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.append(w)

        candidates = sorted(set(weights))

        def all_reach_zero(limit: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            queue = [0]
            for v in queue:
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        queue.append(u)
