class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # State (a, b): colors of a symmetric pair, from left to right.
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in pairs]

